// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("explain_a_missed_deployment",
			mcplib.WithDescription("Shows every target assignment resolving onto that computer, which scope matched, and which rules were shadowed."),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Override the recipe's positional id value.")),
		),
		handleExplainAMissedDeployment,
	)
	s.AddTool(
		mcplib.NewTool("check_reach_before_editing_a_shared_script",
			mcplib.WithDescription("Walks the script to its consuming tasks and packages and out to the computers those assignments resolve onto."),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Override the recipe's positional id value.")),
		),
		handleCheckReachBeforeEditingASharedScript,
	)
}

// handleExplainAMissedDeployment runs the explain_a_missed_deployment recipe intent: Shows every target assignment resolving onto that computer, which scope matched, and which rules were shadowed.
func handleExplainAMissedDeployment(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	if recipeCLIPathErr != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("companion CLI binary not found: %v", recipeCLIPathErr)), nil
	}

	input := req.GetArguments()
	args := []string{}
	args = append(args, "assignment-explain")
	var missingId bool
	args, missingId = appendRecipePositional(args, input["id"], true)
	if missingId {
		return mcplib.NewToolResultError("id is required"), nil
	}
	args = append(args, "--agent")

	out, err := cobratree.RunCLICommand(ctx, recipeCLIPath, args)
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	return cobratree.ToolResultFromCLICommand(out), nil
}

